[DatacontractAttribute]
public class METRPAGeneralJournalWorkflowSubmissionResponse
{ 
    BatchJournalId                  batchJournalId;
    NoYes          	                noYes;
    str                             headerLevelError;
    str                             lineLevelError, workflowStatus;
    boolean                         journalBatchStatus;

}

Method.Source:
    [DataMemberAttribute('Journal batch number')]

    public BatchJournalId parmBatchJournalId(BatchJournalId _batchJournalId = batchJournalId)
    {
        batchJournalId = _batchJournalId;
        return batchJournalId;
    }

    [DataMemberAttribute('Header level status')]
    public NoYes parmHeaderLevelStatus(NoYes _noYes = noYes)
    {
        noYes = _noYes;

        return noYes;
    }

    [DataMemberAttribute('Header level error')]

    public str parmHeaderLevelError(str _headerLevelError = headerLevelError)
    {
        headerLevelError = _headerLevelError;

        return headerLevelError;
    }

    [DataMemberAttribute('Line level errors')]
    public str parmLineLevelJsonofErrors(str _lineLevelError = lineLevelError)
    {
        lineLevelError = _lineLevelError;

        return lineLevelError;
    }

    [DataMemberAttribute('Submit to workflow outcome')]
    public boolean parmSubmitToWorkflowOutcome(boolean _journalBatchStatus = journalBatchStatus)
    {
        journalBatchStatus = _journalBatchStatus;

        return journalBatchStatus;
    }

    [DataMemberAttribute('Workflow status')]

    public str parmWorkflowStatus(str _workflowStatus = workflowStatus)
    {
        workflowStatus = _workflowStatus;

        return workflowStatus;
    }
